SELECT     CONCAT(replace(SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2), '.', ''), '月') AS month,     replace(SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2), '.', '') AS month_num,     SUM(CASE WHEN tqlx in (52, 55, 56, 58, 61, 64, 65, 67, 92) THEN djtqje ELSE 0 END) AS gftqzb,     SUM(CASE WHEN tqlx not in (52, 55, 56, 58, 61, 64, 65, 67, 92) THEN djtqje ELSE 0 END) AS qttqzb FROM     dws_bus_ft_per_qfq WHERE     SUBSTRING(CAST(tjzq AS VARCHAR), 1, 4) = #{ssnd} GROUP BY     CONCAT(SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2), '月'),     SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2) ORDER BY     month_num
